<script setup>
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {api} from '../services/api'
import {useEventStore} from '../stores/event'
const events=useEventStore(),keys=ref([]),webhooks=ref([]),deliveries=ref([]),newKey=ref(null),newWebhook=ref(null),error=ref(''),showKey=ref(false),showWebhook=ref(false)
const eventId=computed(()=>events.currentId)
const keyForm=reactive({name:'Integration Key',scopes:['events.read','attendees.read','sessions.read','analytics.read']})
const webhookForm=reactive({url:'',events:['*']})
async function load(){if(!events.loaded)await events.load();try{[keys.value,webhooks.value,deliveries.value]=await Promise.all([api.developerKeys(),eventId.value?api.developerWebhooks(eventId.value):Promise.resolve([]),eventId.value?api.developerWebhookDeliveries(eventId.value):Promise.resolve([])])}catch(e){error.value=e.message}}
onMounted(load);watch(eventId,load)
async function createKey(){try{newKey.value=await api.createDeveloperKey({...keyForm,event_id:eventId.value});keys.value.unshift({...newKey.value,key:undefined});showKey.value=false}catch(e){error.value=e.message}}
async function revokeKey(row){try{Object.assign(row,await api.revokeDeveloperKey(row.id))}catch(e){error.value=e.message}}
async function createWebhook(){try{const row=await api.createDeveloperWebhook({...webhookForm,event_id:eventId.value});newWebhook.value=row;webhooks.value.unshift({...row,secret:undefined});showWebhook.value=false}catch(e){error.value=e.message}}
async function toggleWebhook(row){try{Object.assign(row,await api.updateDeveloperWebhook(row.id,{active:!row.active}))}catch(e){error.value=e.message}}
</script>
<template><div class="space-y-6"><section class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="eyebrow">Developer Platform</p><h1 class="page-title">APIs & Webhooks</h1><p class="page-subtitle">Scoped external API keys and signed webhook delivery for {{events.current?.name||'your events'}}.</p></div><div class="flex gap-2"><button class="btn-secondary" :disabled="!eventId" @click="showWebhook=true">+ Webhook</button><button class="btn-primary" :disabled="!eventId" @click="showKey=true">+ API Key</button></div></section><p v-if="error" class="rounded-xl bg-rose-50 p-4 text-sm font-semibold text-rose-700">{{error}}</p><div v-if="newKey?.key" class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><b>Copy this API key now. It will not be shown again.</b><p class="mt-3 break-all rounded-xl bg-slate-950 p-3 font-mono text-xs text-cyan-200">{{newKey.key}}</p><button class="btn-secondary mt-3" @click="newKey=null">I saved it</button></div><div v-if="newWebhook?.secret" class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><b>Copy this webhook signing secret now. It will not be shown again.</b><p class="mt-3 break-all rounded-xl bg-slate-950 p-3 font-mono text-xs text-cyan-200">{{newWebhook.secret}}</p><button class="btn-secondary mt-3" @click="newWebhook=null">I saved it</button></div><section class="grid gap-5 xl:grid-cols-2"><article class="panel overflow-hidden"><div class="border-b p-5"><p class="panel-kicker">API keys</p></div><div class="divide-y"><div v-for="k in keys" :key="k.id" class="p-5"><div class="flex justify-between gap-3"><div><b>{{k.name}}</b><p class="mt-1 font-mono text-xs text-slate-400">{{k.prefix}}…</p></div><span class="status-badge" :class="k.active?'badge-published':'badge-draft'">{{k.active?'active':'revoked'}}</span></div><p class="mt-3 text-xs text-slate-500">{{k.scopes.join(' · ')}}</p><button v-if="k.active" class="btn-secondary mt-3 py-1.5 text-rose-600" @click="revokeKey(k)">Revoke</button></div><p v-if="!keys.length" class="p-8 text-center text-sm text-slate-400">No API keys.</p></div></article><article class="panel overflow-hidden"><div class="border-b p-5"><p class="panel-kicker">Signed webhooks</p></div><div class="divide-y"><div v-for="w in webhooks" :key="w.id" class="p-5"><div class="flex justify-between gap-3"><div class="min-w-0"><b class="break-all">{{w.url}}</b><p class="mt-1 text-xs text-slate-400">{{w.events.join(', ')}}</p></div><button class="status-badge" :class="w.active?'badge-published':'badge-draft'" @click="toggleWebhook(w)">{{w.active?'active':'disabled'}}</button></div></div><p v-if="!webhooks.length" class="p-8 text-center text-sm text-slate-400">No webhooks.</p></div></article></section><section class="panel overflow-hidden"><div class="border-b p-5"><p class="panel-kicker">Webhook deliveries</p><h2 class="panel-title">Recent delivery attempts</h2></div><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Event</th><th>Endpoint</th><th>Status</th><th>Attempts</th><th>Updated</th><th>Error</th></tr></thead><tbody><tr v-if="!deliveries.length"><td colspan="6" class="text-center">No webhook deliveries yet.</td></tr><tr v-for="d in deliveries" :key="d.id"><td class="font-mono text-xs">{{d.event}}</td><td class="max-w-xs truncate text-xs">{{d.url}}</td><td><span class="status-badge" :class="d.status==='sent'?'badge-published':d.status==='failed'?'bg-rose-100 text-rose-700':'badge-draft'">{{d.status}}</span></td><td>{{d.attempts||0}}</td><td>{{(d.updated_at||d.created_at)?.slice(0,19).replace('T',' ')}}</td><td class="max-w-xs truncate text-xs text-rose-600">{{d.last_error||'—'}}</td></tr></tbody></table></div></section><section class="panel p-6"><p class="panel-kicker">External API</p><pre class="mt-4 overflow-x-auto rounded-2xl bg-slate-950 p-5 text-xs leading-6 text-cyan-200">GET /digisangam/api/v1/developer/v1/events/{event_id}
GET /digisangam/api/v1/developer/v1/events/{event_id}/attendees
GET /digisangam/api/v1/developer/v1/events/{event_id}/sessions
GET /digisangam/api/v1/developer/v1/events/{event_id}/analytics

X-DigiSangam-Key: dsk_...</pre></section>
<div v-if="showKey" class="modal-backdrop" @click.self="showKey=false"><form class="modal-card" @submit.prevent="createKey"><h2 class="text-lg font-bold">Create API key</h2><label class="field mt-5"><span>Name</span><input v-model="keyForm.name"/></label><div class="mt-4 space-y-2"><label v-for="s in ['events.read','attendees.read','sessions.read','analytics.read']" :key="s" class="flex items-center gap-2 text-sm"><input v-model="keyForm.scopes" type="checkbox" :value="s"/>{{s}}</label></div><div class="mt-6 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="showKey=false">Cancel</button><button class="btn-primary">Create</button></div></form></div>
<div v-if="showWebhook" class="modal-backdrop" @click.self="showWebhook=false"><form class="modal-card" @submit.prevent="createWebhook"><h2 class="text-lg font-bold">Create webhook</h2><label class="field mt-5"><span>HTTPS endpoint</span><input v-model="webhookForm.url" type="url" required/></label><label class="field mt-4"><span>Events</span><input :value="webhookForm.events.join(', ')" @input="webhookForm.events=$event.target.value.split(',').map(x=>x.trim()).filter(Boolean)" placeholder="* or attendee.checked_in"/></label><div class="mt-6 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="showWebhook=false">Cancel</button><button class="btn-primary">Create</button></div></form></div>
</div></template>
